How much whole milk powder was produced:
SELECT *
FROM (
  SELECT Measure, Value, Periods
  FROM "data/en/odata3/7425eng.parquet"
  UNPIVOT(Value FOR Measure IN ('WholeMilkPowder_7'))
  WHERE Periods IN ('2005MM03', '2005MM04')
)
PIVOT(
  SUM(Value) FOR Periods IN ('2005MM03', '2005MM04') GROUP BY Measure
);

How much natural gas was delivered to pu:
SELECT *
FROM (
  SELECT Measure, Value, Periods
  FROM "data/en/odata3/82117ENG.parquet"
  UNPIVOT(Value FOR Measure IN ('NaturalGasDelivered_1'))
  WHERE SectorBranchSIC2008 IN ('417400', '440900', '428100')
)
PIVOT(
  SUM(Value) FOR Periods IN ('2018JJ00') GROUP BY Measure
);
